UPDATE loan_maturity_overdue
SET paid_carried_delinquency_charge = paid_carried_delinquency_charge + #{amount}
WHERE loan_maturity_overdue_id = #{loanMaturityOverdueId}

UPDATE loan_maturity_overdue
SET paid_carried_interest = paid_carried_interest + #{amount}
WHERE loan_maturity_overdue_id = #{loanMaturityOverdueId}
